package com.dbtraining.reconx.service;
import com.dbtraining.reconx.dto.TradeEvent; import com.dbtraining.reconx.repository.AuditLogRepository; import com.fasterxml.jackson.databind.JsonNode; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.stereotype.Service; import java.util.Optional;
@Service public class TradeAggregator { private final AuditLogRepository audit; private final ObjectMapper json; public TradeAggregator(AuditLogRepository audit,ObjectMapper json){this.audit=audit;this.json=json;} public Optional<JsonNode> rebuild(String tradeRef){JsonNode state=null;for(var event:audit.findByTradeRefOrderByEventTimestampAsc(tradeRef)){try{switch(TradeEvent.EventType.valueOf(event.getEventType())){case TRADE_CREATED,TRADE_UPDATED -> state=event.getAfterState()==null?null:json.readTree(event.getAfterState());case TRADE_CANCELLED -> state=null;}}catch(Exception e){throw new IllegalStateException("Cannot rebuild "+tradeRef,e);}}return Optional.ofNullable(state);}}
